!function(){"use strict";app.factory("etiquetaService",(function(mainService){let url="Etiqueta/";return{getAll:function(query){return mainService.getData("get",url+"Get/"+query,null,!0).then(response=>{if("0"===response.code)throw response;if("1"===response.code){let etiquetas;return JSON.parse(response.payload).map(item=>({idEtiqueta:item.idEtiqueta,descripcion:item.descripcion,etiquetas:item.etiquetas,estado:item.estado}))}})},create:function(data){return mainService.getData("post",url+"Insert?json="+JSON.stringify(data),null,!0).then(response=>{if("0"===response.code)throw response;if("1"===response.code)return response})},update:function(id,data){return mainService.getData("put",url+"Update/"+id+JSON.stringify(data),null,!0).then(response=>{if("0"===response.code)throw new Error(response);if("1"===response.code)return response})},delete:function(id){return mainService.getData("delete",url+"Delete/"+id,null,!0).then(response=>{if("0"===response.code)throw new Error(response);if("1"===response.code)return response})}}}))}(window.angular);